121→ 	}
122→ 
123→ 	// Result = H1 + (H2 - H1) * fraction.
124→ 	result := h2.Copy()
125→ 	_, _, nhcbReconciled, err := result.Sub(h1)
126→ 	if err != nil {
127→ 		return nil, err
128→ 	}
129→ 	if nhcbReconciled {
130→ 		annos.Add(annotations.NewMismatchedCustomBucketsHistogramsInfo(pos, annotations.HistogramSub))
131→ 	}
132→ 	result.Mul(fraction)
133→ 	_, _, nhcbReconciled, err = result.Add(h1)
134→ 	if err != nil {
135→ 		return nil, err
136→ 	}
137→ 	if nhcbReconciled {
138→ 		annos.Add(annotations.NewMismatchedCustomBucketsHistogramsInfo(pos, annotations.HistogramAdd))
139→ 	}
140→ 	return result, nil
141→ }
