143→ // pickOrInterpolateLeftHistogram returns the histogram at the left boundary of the range.
144→ // If interpolation is needed (when smoothed is true and the first sample is before the range start),
145→ // it returns the interpolated histogram at the left boundary; otherwise, it returns a copy of the first sample's histogram.
146→ func pickOrInterpolateLeftHistogram(hists []HPoint, first int, rangeStart int64, smoothed, isCounter bool, annos *annotations.Annotations, pos posrange.PositionRange) (*histogram.FloatHistogram, error) {
147→ 	if smoothed && hists[first].T < rangeStart {
148→ 		return interpolateHistograms(hists[first].H, hists[first].T, hists[first+1].H, hists[first+1].T, rangeStart, isCounter, annos, pos)
149→ 	}
150→ 	return hists[first].H.Copy(), nil
151→ }
152→ 
153→ // pickOrInterpolateRightHistogram returns the histogram at the right boundary of the range.
154→ // If interpolation is needed (when smoothed is true and the last sample is after the range end),
155→ // it returns the interpolated histogram at the right boundary; otherwise, it returns a copy of the last sample's histogram.
156→ func pickOrInterpolateRightHistogram(hists []HPoint, last int, rangeEnd int64, smoothed, isCounter bool, annos *annotations.Annotations, pos posrange.PositionRange) (*histogram.FloatHistogram, error) {
157→ 	if smoothed && last > 0 && hists[last].T > rangeEnd {
158→ 		return interpolateHistograms(hists[last-1].H, hists[last-1].T, hists[last].H, hists[last].T, rangeEnd, isCounter, annos, pos)
159→ 	}
160→ 	return hists[last].H.Copy(), nil
161→ }
