163→ // correctForCounterResets calculates the correction for counter resets.
164→ // This function is only used for extendedRate functions with smoothed or anchored rates.
165→ func correctForCounterResets(left, right float64, points []FPoint) float64 {
166→ 	var correction float64
167→ 	prev := left
168→ 	for _, p := range points {
169→ 		if p.F < prev {
170→ 			correction += prev
171→ 		}
172→ 		prev = p.F
173→ 	}
174→ 	if right < prev {
175→ 		correction += prev
176→ 	}
177→ 	return correction
178→ }
